-- CAREEROS P3-T01: plans, subscriptions, feature flags, audit log and the organization plan and status (phase plan D2,
-- D3, D4, D7). The CREATE TABLE and index statements are generated by drizzle-kit; everything else is written by hand,
-- following P1-T09 and P2-T01, and is idempotent where it can be (the generated DDL is not). Runs as the migration
-- (owner) role. Down migration: down.sql in this folder.
--> statement-breakpoint
-- 0. A time-sortable id (uuidv7) for audit_log rows written in SQL. PostgreSQL 16 has no uuidv7(): 48 bits of
-- millisecond timestamp, then random bits with the version nibble set to 7. The application generates the same kind of
-- id with generateId(). Created first because audit_log's column default calls it.
CREATE OR REPLACE FUNCTION public.careeros_uuidv7() RETURNS uuid
LANGUAGE sql VOLATILE SET search_path = pg_catalog AS $$
	SELECT encode(
		set_bit(set_bit(
			overlay(uuid_send(gen_random_uuid()) PLACING substring(int8send((extract(epoch FROM clock_timestamp()) * 1000)::bigint) FROM 3) FROM 1 FOR 6),
			52, 1), 53, 1),
		'hex')::uuid
$$;
--> statement-breakpoint
CREATE TABLE "audit_log" (
	"id" text PRIMARY KEY DEFAULT public.careeros_uuidv7()::text,
	"organization_id" text,
	"actor_user_id" text,
	"impersonator_user_id" text,
	"action" text NOT NULL,
	"target_type" text,
	"target_id" text,
	"metadata" jsonb DEFAULT '{}' NOT NULL,
	"ip" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "audit_log_action_check" CHECK ("action" ~ '^[a-z][a-z0-9_.]{1,63}$')
);
--> statement-breakpoint
