-- 2. Row-level security (D4), as P1-T04 and P2-T01: FORCE applies the policy to the table owner too, so only
-- owner_access lets the owner role (migrations, definer functions) see every organization. careeros_app only matches its
-- own organization; an unset setting is NULL and matches nothing (fail closed).
-- The app-role policies are per command and cover only what the app may do (SELECT; INSERT for audit_log). With FORCE
-- RLS, a command without a policy is denied, so a blanket table grant (infra/db/bootstrap-roles.sql re-grants all four
-- privileges on every table, which would undo a REVOKE) still cannot write these tables. The REVOKEs in section 3 and the
-- matching lines in bootstrap-roles.sql are the second layer.
-- plan is global (no organization_id): every role may read it, and only the owner may write.
ALTER TABLE "plan" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "plan" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
DROP POLICY IF EXISTS "plan_read" ON "plan";--> statement-breakpoint
CREATE POLICY "plan_read" ON "plan" FOR SELECT USING (true);--> statement-breakpoint
DROP POLICY IF EXISTS "owner_access" ON "plan";--> statement-breakpoint
CREATE POLICY "owner_access" ON "plan" TO CURRENT_USER USING (true) WITH CHECK (true);--> statement-breakpoint
ALTER TABLE "subscription" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "subscription" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
DROP POLICY IF EXISTS "tenant_isolation" ON "subscription";--> statement-breakpoint
CREATE POLICY "tenant_isolation" ON "subscription" FOR SELECT
	USING ("organization_id" = current_setting('app.current_org_id', true));--> statement-breakpoint
DROP POLICY IF EXISTS "owner_access" ON "subscription";--> statement-breakpoint
CREATE POLICY "owner_access" ON "subscription" TO CURRENT_USER USING (true) WITH CHECK (true);--> statement-breakpoint
-- feature_flag: the current organization's flags and the global ones (null organization).
ALTER TABLE "feature_flag" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "feature_flag" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
DROP POLICY IF EXISTS "tenant_isolation" ON "feature_flag";--> statement-breakpoint
CREATE POLICY "tenant_isolation" ON "feature_flag" FOR SELECT
	USING ("organization_id" = current_setting('app.current_org_id', true) OR "organization_id" IS NULL);--> statement-breakpoint
DROP POLICY IF EXISTS "owner_access" ON "feature_flag";--> statement-breakpoint
CREATE POLICY "owner_access" ON "feature_flag" TO CURRENT_USER USING (true) WITH CHECK (true);--> statement-breakpoint
-- audit_log: append-only for the app role. It reads and inserts rows of the current organization; platform rows (null
-- organization) are invisible to it and are written only by careeros_audit_platform. There is no UPDATE or DELETE policy.
ALTER TABLE "audit_log" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "audit_log" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
DROP POLICY IF EXISTS "tenant_isolation" ON "audit_log";--> statement-breakpoint
CREATE POLICY "tenant_isolation" ON "audit_log" FOR SELECT
	USING ("organization_id" = current_setting('app.current_org_id', true));--> statement-breakpoint
DROP POLICY IF EXISTS "tenant_insert" ON "audit_log";--> statement-breakpoint
CREATE POLICY "tenant_insert" ON "audit_log" FOR INSERT
	WITH CHECK ("organization_id" = current_setting('app.current_org_id', true));--> statement-breakpoint
DROP POLICY IF EXISTS "owner_access" ON "audit_log";--> statement-breakpoint
CREATE POLICY "owner_access" ON "audit_log" TO CURRENT_USER USING (true) WITH CHECK (true);--> statement-breakpoint
-- 3. Table privileges. New tables get SELECT, INSERT, UPDATE and DELETE for careeros_app from the default privileges of
-- infra/db/bootstrap-roles.sql; take back what the app role must not have. (A fresh test database migrates before the
-- role exists, so the REVOKE is conditional; the bootstrap script repeats it after its blanket GRANT.)
DO $$ BEGIN
	IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'careeros_app') THEN
		REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON TABLE public.plan, public.subscription, public.feature_flag FROM careeros_app;
		REVOKE UPDATE, DELETE, TRUNCATE ON TABLE public.audit_log FROM careeros_app;
	END IF;
END $$;--> statement-breakpoint
-- 4. Backfill: one subscription row per existing organization, on the plan the organization has, with no provider.
INSERT INTO "subscription" ("organization_id", "plan_id") SELECT o."id", o."plan_id" FROM "organization" o ON CONFLICT DO NOTHING;--> statement-breakpoint
-- 5. New organizations get their subscription row in the statement that creates them, by the mechanism P2-T01 uses for
-- branding rows: an AFTER INSERT trigger running a definer function, so it works whichever role or organization context
-- inserted the organization (the plugin, the signup hook, backfills, tests).
CREATE OR REPLACE FUNCTION public.create_organization_subscription() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
BEGIN
	INSERT INTO public.subscription (organization_id, plan_id) VALUES (NEW.id, NEW.plan_id) ON CONFLICT DO NOTHING;
	RETURN NEW;
END
$$;--> statement-breakpoint
DROP TRIGGER IF EXISTS "careeros_organization_subscription" ON "organization";--> statement-breakpoint
CREATE TRIGGER "careeros_organization_subscription" AFTER INSERT ON "organization"
	FOR EACH ROW EXECUTE FUNCTION public.create_organization_subscription();--> statement-breakpoint
-- 6. The app role cannot choose or change an organization's plan or status. A trigger, not a column REVOKE: the
-- bootstrap script re-grants UPDATE on whole tables, and a table-level privilege overrides a column-level REVOKE, so a
-- REVOKE would not survive a deploy. The trigger function is not SECURITY DEFINER, so current_user is the role that
-- runs the statement: careeros_app for a direct statement, the function owner inside a definer function (see
-- careeros_set_org_plan). A custom setting (a "billing_write" flag) was rejected because the app role can set any
-- custom setting itself.
--   - INSERT by the app role: the organization must start as active on the personal plan (the column defaults). The
--     organization plugin inserts without these columns, so it is unaffected.
--   - UPDATE by the app role: status, plan_id and status_changed_at must not change. Other columns update as before.
CREATE OR REPLACE FUNCTION public.careeros_organization_plan_guard() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
BEGIN
	IF current_user <> 'careeros_app' THEN
		RETURN NEW;
	END IF;
	IF TG_OP = 'INSERT' THEN
		IF NEW.status IS DISTINCT FROM 'active' OR NEW.plan_id IS DISTINCT FROM 'personal' OR NEW.status_changed_at IS NOT NULL THEN
			RAISE EXCEPTION 'careeros_billing: organization plan and status are set by the platform only' USING ERRCODE = '42501';
		END IF;
	ELSIF NEW.status IS DISTINCT FROM OLD.status OR NEW.plan_id IS DISTINCT FROM OLD.plan_id
		OR NEW.status_changed_at IS DISTINCT FROM OLD.status_changed_at THEN
		RAISE EXCEPTION 'careeros_billing: organization plan and status are set by the platform only' USING ERRCODE = '42501';
	END IF;
	RETURN NEW;
END
$$;--> statement-breakpoint
DROP TRIGGER IF EXISTS "careeros_organization_plan_guard" ON "organization";--> statement-breakpoint
CREATE TRIGGER "careeros_organization_plan_guard" BEFORE INSERT OR UPDATE ON "organization"
	FOR EACH ROW EXECUTE FUNCTION public.careeros_organization_plan_guard();--> statement-breakpoint
-- 7. Definer functions: the only writers of plan, status and subscription state. They run as the owner (owner_access
-- policies), pin search_path, and write their audit row in the same transaction as the change. They check nothing about
-- the CALLER: T04 (billing events) and T07 (platform admins) check that in TypeScript, and each caller is reviewed then.
-- Parameters start with p_ so they cannot be mistaken for the columns of the same name.
--
-- careeros_set_org_plan: sets an organization's plan and/or status. A null p_plan_id or p_status leaves that value
-- as it is. Updates organization.plan_id, status and status_changed_at (only when the status changes) and the plan of
-- the subscription row (created if missing). Writes org.plan_changed and/or org.status_changed to audit_log with
-- {from, to, reason}. A call that changes nothing writes nothing.
CREATE OR REPLACE FUNCTION public.careeros_set_org_plan(
	p_org_id text, p_plan_id text, p_status text, p_actor_user_id text, p_reason text
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
	org public.organization%ROWTYPE;
	new_plan text;
	new_status text;
BEGIN
	SELECT * INTO org FROM public.organization WHERE id = p_org_id FOR UPDATE;
	IF NOT FOUND THEN
		RAISE EXCEPTION 'careeros_set_org_plan: unknown organization';
	END IF;
	new_plan := coalesce(p_plan_id, org.plan_id);
	new_status := coalesce(p_status, org.status);
	IF NOT EXISTS (SELECT 1 FROM public.plan WHERE id = new_plan) THEN
		RAISE EXCEPTION 'careeros_set_org_plan: unknown plan %', new_plan;
	END IF;
	IF new_status NOT IN ('trial', 'active', 'past_due', 'suspended') THEN
		RAISE EXCEPTION 'careeros_set_org_plan: unknown status %', new_status;
	END IF;
	UPDATE public.organization
		SET plan_id = new_plan, status = new_status,
			status_changed_at = CASE WHEN new_status IS DISTINCT FROM org.status THEN now() ELSE org.status_changed_at END
		WHERE id = p_org_id;
	INSERT INTO public.subscription (organization_id, plan_id) VALUES (p_org_id, new_plan)
		ON CONFLICT (organization_id) DO UPDATE SET plan_id = excluded.plan_id, updated_at = now();
	IF new_plan IS DISTINCT FROM org.plan_id THEN
		INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_type, target_id, metadata)
		VALUES (p_org_id, p_actor_user_id, 'org.plan_changed', 'organization', p_org_id,
			jsonb_build_object('from', org.plan_id, 'to', new_plan, 'reason', p_reason));
	END IF;
	IF new_status IS DISTINCT FROM org.status THEN
		INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_type, target_id, metadata)
		VALUES (p_org_id, p_actor_user_id, 'org.status_changed', 'organization', p_org_id,
			jsonb_build_object('from', org.status, 'to', new_status, 'reason', p_reason));
	END IF;
END
$$;--> statement-breakpoint
-- careeros_set_subscription: updates the subscription row from an allow-listed set of fields (everything except the
-- plan, which only careeros_set_org_plan changes, and the timestamps the function keeps itself). An unknown key, a
-- non-object, an empty source or a missing row raises. The values go through jsonb_populate_record, so a wrong type or
-- a value the CHECK constraints refuse raises too. Writes subscription.updated with {source, fields} in the same
-- transaction. An empty object changes nothing and writes nothing.
CREATE OR REPLACE FUNCTION public.careeros_set_subscription(
	p_org_id text, p_fields jsonb, p_actor_user_id text, p_source text
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
	allowed text[] := ARRAY[
		'provider', 'provider_customer_id', 'provider_subscription_id', 'status', 'seats', 'billing_interval',
		'current_period_start', 'current_period_end', 'trial_ends_at', 'grace_ends_at', 'ai_overage_allowed'
	];
	unknown_keys text[];
	rec public.subscription;
BEGIN
	IF p_fields IS NULL OR jsonb_typeof(p_fields) <> 'object' THEN
		RAISE EXCEPTION 'careeros_set_subscription: fields must be a JSON object';
	END IF;
	IF p_source IS NULL OR btrim(p_source) = '' THEN
		RAISE EXCEPTION 'careeros_set_subscription: a source is required';
	END IF;
	SELECT array_agg(k ORDER BY k) INTO unknown_keys FROM jsonb_object_keys(p_fields) AS k WHERE k <> ALL (allowed);
	IF unknown_keys IS NOT NULL THEN
		RAISE EXCEPTION 'careeros_set_subscription: unknown fields %', array_to_string(unknown_keys, ', ');
	END IF;
	PERFORM 1 FROM public.subscription WHERE organization_id = p_org_id FOR UPDATE;
	IF NOT FOUND THEN
		RAISE EXCEPTION 'careeros_set_subscription: no subscription for the organization';
	END IF;
	IF p_fields = '{}'::jsonb THEN
		RETURN;
	END IF;
	rec := jsonb_populate_record(NULL::public.subscription, p_fields);
	UPDATE public.subscription s SET
		provider = CASE WHEN p_fields ? 'provider' THEN rec.provider ELSE s.provider END,
		provider_customer_id = CASE WHEN p_fields ? 'provider_customer_id' THEN rec.provider_customer_id ELSE s.provider_customer_id END,
		provider_subscription_id = CASE WHEN p_fields ? 'provider_subscription_id' THEN rec.provider_subscription_id ELSE s.provider_subscription_id END,
		status = CASE WHEN p_fields ? 'status' THEN rec.status ELSE s.status END,
		seats = CASE WHEN p_fields ? 'seats' THEN rec.seats ELSE s.seats END,
		billing_interval = CASE WHEN p_fields ? 'billing_interval' THEN rec.billing_interval ELSE s.billing_interval END,
		current_period_start = CASE WHEN p_fields ? 'current_period_start' THEN rec.current_period_start ELSE s.current_period_start END,
		current_period_end = CASE WHEN p_fields ? 'current_period_end' THEN rec.current_period_end ELSE s.current_period_end END,
		trial_ends_at = CASE WHEN p_fields ? 'trial_ends_at' THEN rec.trial_ends_at ELSE s.trial_ends_at END,
		grace_ends_at = CASE WHEN p_fields ? 'grace_ends_at' THEN rec.grace_ends_at ELSE s.grace_ends_at END,
		ai_overage_allowed = CASE WHEN p_fields ? 'ai_overage_allowed' THEN rec.ai_overage_allowed ELSE s.ai_overage_allowed END,
		updated_at = now()
	WHERE s.organization_id = p_org_id;
	INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_type, target_id, metadata)
	VALUES (p_org_id, p_actor_user_id, 'subscription.updated', 'subscription', p_org_id,
		jsonb_build_object('source', p_source, 'fields', p_fields));
END
$$;--> statement-breakpoint
-- careeros_audit_platform: writes a platform-level audit row (null organization) and returns its id. The app role
-- cannot insert such a row itself (the INSERT policy requires the current organization). The action must match the
-- audit_log CHECK pattern.
CREATE OR REPLACE FUNCTION public.careeros_audit_platform(
	p_actor_user_id text, p_impersonator_user_id text, p_action text, p_target_type text, p_target_id text,
	p_metadata jsonb, p_ip text
) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
	new_id text;
BEGIN
	INSERT INTO public.audit_log (organization_id, actor_user_id, impersonator_user_id, action, target_type, target_id, metadata, ip)
	VALUES (NULL, p_actor_user_id, p_impersonator_user_id, p_action, p_target_type, p_target_id, coalesce(p_metadata, '{}'::jsonb), p_ip)
	RETURNING id INTO new_id;
	RETURN new_id;
END
$$;--> statement-breakpoint
DO $$ BEGIN
	REVOKE ALL ON FUNCTION public.careeros_uuidv7() FROM PUBLIC;
	REVOKE ALL ON FUNCTION public.create_organization_subscription() FROM PUBLIC;
	REVOKE ALL ON FUNCTION public.careeros_organization_plan_guard() FROM PUBLIC;
	REVOKE ALL ON FUNCTION public.careeros_set_org_plan(text, text, text, text, text) FROM PUBLIC;
	REVOKE ALL ON FUNCTION public.careeros_set_subscription(text, jsonb, text, text) FROM PUBLIC;
	REVOKE ALL ON FUNCTION public.careeros_audit_platform(text, text, text, text, text, jsonb, text) FROM PUBLIC;
	IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'careeros_app') THEN
		GRANT EXECUTE ON FUNCTION public.careeros_uuidv7() TO careeros_app;
		GRANT EXECUTE ON FUNCTION public.careeros_organization_plan_guard() TO careeros_app;
		GRANT EXECUTE ON FUNCTION public.careeros_set_org_plan(text, text, text, text, text) TO careeros_app;
		GRANT EXECUTE ON FUNCTION public.careeros_set_subscription(text, jsonb, text, text) TO careeros_app;
		GRANT EXECUTE ON FUNCTION public.careeros_audit_platform(text, text, text, text, text, jsonb, text) TO careeros_app;
	END IF;
END $$;
